using System;using System.IO;using System.Linq;using System.Text;using System.Xml.Linq;
// Actual canonical plan Write/Build/TryRead. Explicit detached item/native actor
// codecs, removal envelope and generic bag planner adapters; no native effects.
class ItemStack{internal string Name;internal int count;internal ItemStack(string name,int n){Name=name;count=n;}internal ItemStack Clone()=>new ItemStack(Name,count);internal static ItemStack[] Clone(ItemStack[] items)=>items.Select(i=>i.Clone()).ToArray();}
static class RebirthCamperInventorySnapshot{internal static byte[] Capture(ItemStack[] items)=>Encoding.UTF8.GetBytes(string.Join(";",items.Select(i=>i.Name+":"+i.count)));internal static ItemStack[] Restore(byte[] bytes){string text=Encoding.UTF8.GetString(bytes);return text==""?new ItemStack[0]:text.Split(';').Select(v=>{var p=v.Split(':');return new ItemStack(p[0],int.Parse(p[1]));}).ToArray();}}
class RebirthCamperEnergyActorImage{internal ItemStack Cursor;internal ItemStack[] Bag,Belt;internal bool[] BagLocks;internal RebirthCamperEnergyActorImage Copy()=>new RebirthCamperEnergyActorImage{Cursor=Cursor.Clone(),Bag=ItemStack.Clone(Bag),Belt=ItemStack.Clone(Belt),BagLocks=(bool[])BagLocks.Clone()};internal bool Matches(RebirthCamperEnergyActorImage image)=>RebirthRemoteResourceClientOriginal.ActorImage(this)==RebirthRemoteResourceClientOriginal.ActorImage(image);}
static class RebirthRemoteResourceClientOriginal{internal static string ActorImage(RebirthCamperEnergyActorImage image)=>string.Join("^",new[]{Convert.ToBase64String(RebirthCamperInventorySnapshot.Capture(new[]{image.Cursor})),Convert.ToBase64String(RebirthCamperInventorySnapshot.Capture(image.Bag)),Convert.ToBase64String(RebirthCamperInventorySnapshot.Capture(image.Belt)),new string(image.BagLocks.Select(b=>b?'1':'0').ToArray())});internal static RebirthCamperEnergyActorImage ReadActor(string text){var parts=text.Split('^');return new RebirthCamperEnergyActorImage{Cursor=RebirthCamperInventorySnapshot.Restore(Convert.FromBase64String(parts[0]))[0],Bag=RebirthCamperInventorySnapshot.Restore(Convert.FromBase64String(parts[1])),Belt=RebirthCamperInventorySnapshot.Restore(Convert.FromBase64String(parts[2])),BagLocks=parts[3].Select(c=>c=='1').ToArray()};}}
static class RebirthStationPublicationRecord{internal static string Digest(byte[] bytes){using(var sha=System.Security.Cryptography.SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}}
static class RebirthCookingRemoteAdmissionBackend{internal static Guid StationKey(string world,string value){using(var sha=System.Security.Cryptography.SHA256.Create())return new Guid(sha.ComputeHash(Encoding.UTF8.GetBytes(world+value)).Take(16).ToArray());}}
static class RebirthStationGridIngredients{internal static bool IsSameStackSnapshot(ItemStack a,ItemStack b)=>a.Name==b.Name&&a.count==b.count;}
static class RebirthCamperEnergyItems{internal static bool Same(ItemStack[] a,ItemStack[] b)=>a.Length==b.Length&&a.Zip(b,(x,y)=>RebirthStationGridIngredients.IsSameStackSnapshot(x,y)).All(v=>v);}
class Address{internal Guid Vehicle,Installation;}
static class RebirthCamperPortableStation{internal static Address Address=new Address{Vehicle=Guid.NewGuid(),Installation=Guid.NewGuid()};internal static bool TryGetSourceAddress(ItemStack carrier,out Address address){address=Address;return carrier.Name=="carrier";}}
static class RebirthCamperStationRemovalContents{internal static ItemStack[] Contents=new[]{new ItemStack("item",4)};internal static bool TryRead(ItemStack carrier,out ItemStack[] items){items=ItemStack.Clone(Contents);return carrier.Name=="carrier";}internal static ItemStack WithoutContents(ItemStack carrier)=>new ItemStack("stripped",carrier.count);}
static class RebirthRecyclerOwnerDelivery{internal static bool PlanWithOverflow(ItemStack[] bag,ItemStack[] belt,bool[] locks,bool[] beltLocks,int owned,ItemStack[] payload,out ItemStack[] nextBag,out ItemStack[] nextBelt,out ItemStack[] overflow){nextBag=ItemStack.Clone(bag);nextBelt=ItemStack.Clone(belt);var left=new System.Collections.Generic.List<ItemStack>();foreach(var source in payload){int remaining=source.count;for(int i=0;i<bag.Length&&remaining>0;i++){if(locks[i]||nextBag[i].Name!="empty"&&nextBag[i].Name!=source.Name)continue;int n=Math.Min(5-nextBag[i].count,remaining);if(n>0){nextBag[i]=new ItemStack(source.Name,nextBag[i].count+n);remaining-=n;}}if(remaining>0)left.Add(new ItemStack(source.Name,remaining));}overflow=left.ToArray();return true;}}
// ACTUAL_PLAN
static class Program
{
 static int checks;static void Check(bool value){checks++;if(!value)throw new Exception("Actual parcel plan assertion "+checks);}
 static RebirthCamperRemovalParcelPlan Plan(int slot=-1,bool full=false){var address=RebirthCamperPortableStation.Address;var value=new RebirthCamperRemovalParcelPlan{Removal=Guid.NewGuid(),Vehicle=address.Vehicle,Installation=address.Installation,World="world",Owner="owner",Creation="creation",Source=new string('a',128),Entity=7,Contents=ItemStack.Clone(RebirthCamperStationRemovalContents.Contents),Carrier=new ItemStack("carrier",1),CarrierSlot=slot,Before=new RebirthCamperEnergyActorImage{Cursor=new ItemStack(slot<0?"carrier":"empty",slot<0?1:0),Bag=new[]{new ItemStack("empty",0),new ItemStack(full?"item":"empty",full?5:0)},Belt=new[]{new ItemStack("empty",0)},BagLocks=new[]{false,false}}};if(slot>=0)value.Before.Bag[slot]=value.Carrier.Clone();value.Operation=RebirthCamperRemovalParcelPlan.Key(value.World,value.Source,value.Owner,value.Creation);value.Freeze();return value;}
 static void Main(){var plan=Plan();Check(plan.Credited.Bag[0].count==4&&plan.Credited.Cursor.Name=="carrier"&&plan.Retired.Cursor.Name=="stripped");Check(plan.Credited.Belt[0].count==0&&plan.Overflow.Length==0);Check(RebirthCamperRemovalParcelPlan.TryRead(plan.Write(),out var read)&&read.Binding==plan.Binding);
 plan=Plan(0,true);Check(plan.Credited.Bag[0].Name=="carrier"&&plan.Overflow[0].count==4&&plan.Retired.Bag[0].Name=="stripped");Check(RebirthCamperRemovalParcelPlan.TryRead(plan.Write(),out read));
 var node=plan.Write();node.SetAttributeValue("operation",Guid.NewGuid().ToString("N"));Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.SetAttributeValue("source",new string('b',128));Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.SetAttributeValue("carrierSlot",1);Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.Element("creditedActor").Value=node.Element("retiredActor").Value;Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.Element("overflow").Value=Convert.ToBase64String(RebirthCamperInventorySnapshot.Capture(new[]{new ItemStack("item",3)}));Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.SetAttributeValue("deaths",-1);Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.SetAttributeValue("entity","007");Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.Add(new XElement("extra"));Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));node=plan.Write();node.SetAttributeValue("installation",Guid.NewGuid().ToString("N"));Check(!RebirthCamperRemovalParcelPlan.TryRead(node,out _));Console.WriteLine(checks+" actual parcel plan assertions passed");}
}
